(() => {
  const dataPath = 'data/stock-descriptions.csv';
  const pricesDir = 'data/indiv-stock';
  const tooltip = d3.select('#tooltip');
  const legend = d3.select('#legend');
  const svg = d3.select('#bubble-svg');
  const bubbleContainer = document.getElementById('bubble-chart');
  const warning = d3.select('#data-warning');
  const parseDate = d3.timeParse('%Y-%m-%d');
  const state = {
    selected: null,
    nodes: null,
    rows: null,
    simulation: null,
    color: null,
    centers: null
  };

  const palette = [
    ...d3.schemeTableau10,
    ...d3.schemeSet3,
    ...d3.schemeSet2,
    '#8c2f39',
    '#3d405b'
  ];

  const formatMarketCap = (value) => {
    if (!Number.isFinite(value) || value <= 0) return '—';
    const abs = Math.abs(value);
    if (abs >= 1e12) return `${(value / 1e12).toFixed(2)}T`;
    if (abs >= 1e9) return `${(value / 1e9).toFixed(2)}B`;
    if (abs >= 1e6) return `${(value / 1e6).toFixed(2)}M`;
    if (abs >= 1e3) return `${(value / 1e3).toFixed(2)}K`;
    return value.toFixed(2);
  };

  const textColorFor = (fill) => {
    const c = d3.color(fill);
    if (!c) return '#111827';
    const luminance = 0.299 * c.r + 0.587 * c.g + 0.114 * c.b;
    return luminance > 170 ? '#111827' : '#f9fafb';
  };

  const showWarning = (message) => {
    warning.style('display', 'block').text(message);
  };

  const setSelected = (ticker) => {
    if (state.selected === ticker) {
      state.selected = null;
    } else {
      state.selected = ticker;
    }
    updateSelection();
  };

  const updateSelection = () => {
    if (state.nodes) {
      state.nodes.classed('selected', (d) => d.ticker === state.selected);
    }
    if (state.rows) {
      state.rows.classed('selected', (d) => d.ticker === state.selected);
    }
  };

  const buildLegend = (sectors, color) => {
    legend.selectAll('*').remove();
    const items = legend
      .selectAll('.legend-item')
      .data(sectors)
      .enter()
      .append('div')
      .attr('class', 'legend-item');

    items.append('span')
      .attr('class', 'legend-swatch')
      .style('background', (d) => color(d));

    items.append('span').text((d) => d);
  };

  const buildTable = (data) => {
    const tbody = d3.select('#stock-table tbody');
    tbody.selectAll('*').remove();

    const rows = tbody
      .selectAll('tr')
      .data(data, (d) => d.ticker)
      .enter()
      .append('tr')
      .on('click', (event, d) => {
        event.stopPropagation();
        setSelected(d.ticker);
      });

    rows.append('td').text((d) => d.ticker);

    const nameCell = rows.append('td').attr('class', 'name-cell');
    nameCell.append('div').attr('class', 'name-text').text((d) => d.fullName);
    nameCell.append('div').attr('class', 'sparkline').attr('data-ticker', (d) => d.ticker);

    rows.append('td').text((d) => d.sector);

    rows.append('td')
      .attr('class', 'market-cap')
      .text((d) => d.displayMarketCap);

    state.rows = rows;
  };

  const drawSparkline = (ticker, series) => {
    const container = d3.select(`.sparkline[data-ticker='${ticker}']`);
    if (container.empty() || !series.length) return;

    const maxPoints = 120;
    let data = series;
    if (series.length > maxPoints) {
      const step = Math.ceil(series.length / maxPoints);
      data = series.filter((_, i) => i % step === 0);
    }

    const width = 120;
    const height = 24;
    const x = d3.scaleTime()
      .domain(d3.extent(data, (d) => d.date))
      .range([0, width]);
    const y = d3.scaleLinear()
      .domain(d3.extent(data, (d) => d.close))
      .nice()
      .range([height - 2, 2]);

    const line = d3.line()
      .x((d) => x(d.date))
      .y((d) => y(d.close));

    const sparkSvg = container.append('svg')
      .attr('width', width)
      .attr('height', height);

    sparkSvg.append('path')
      .datum(data)
      .attr('d', line)
      .attr('fill', 'none')
      .attr('stroke', '#5c6f7b')
      .attr('stroke-width', 1.2);
  };

  const loadSparklines = (data) => {
    const tasks = data.map((d) => {
      const path = `${pricesDir}/${d.ticker}.csv`;
      return d3.csv(path, (row) => ({
        date: parseDate(row.Date),
        close: +row.Close
      }))
        .then((series) => {
          const clean = series.filter((s) => s.date && Number.isFinite(s.close));
          drawSparkline(d.ticker, clean);
        })
        .catch(() => {
          // Silently ignore missing or blocked files.
        });
    });

    Promise.allSettled(tasks).then((results) => {
      if (results.every((r) => r.status === 'rejected')) {
        showWarning('Price history files could not be loaded. If you opened this via file://, try a local server.');
      }
    });
  };

  const buildChart = (data) => {
    const bounds = bubbleContainer.getBoundingClientRect();
    const width = bounds.width;
    const height = bounds.height;
    svg.attr('viewBox', [0, 0, width, height]);

    const sectors = Array.from(new Set(data.map((d) => d.sector)));
    const color = d3.scaleOrdinal()
      .domain(sectors)
      .range(palette.slice(0, sectors.length));

    state.color = color;

    const cols = Math.ceil(Math.sqrt(sectors.length));
    const rows = Math.ceil(sectors.length / cols);
    const xScale = d3.scalePoint()
      .domain(d3.range(cols))
      .range([width * 0.2, width * 0.8]);
    const yScale = d3.scalePoint()
      .domain(d3.range(rows))
      .range([height * 0.2, height * 0.8]);

    const centers = {};
    sectors.forEach((sector, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      centers[sector] = {
        x: xScale(col),
        y: yScale(row)
      };
    });

    state.centers = centers;

    const nonEtfCaps = data.filter((d) => !d.isETF).map((d) => d.marketCapValue);
    const capExtent = d3.extent(nonEtfCaps);
    const radiusScale = d3.scaleSqrt()
      .domain(capExtent)
      .range([18, 54]);
    const etfRadius = 22;

    data.forEach((d) => {
      d.radius = d.isETF ? etfRadius : radiusScale(d.marketCapValue);
    });

    svg.selectAll('*').remove();
    const g = svg.append('g');

    const nodes = g
      .selectAll('g.node')
      .data(data, (d) => d.ticker)
      .enter()
      .append('g')
      .attr('class', 'node')
      .on('mouseenter', (event, d) => {
        if (d.isETF) return;
        tooltip
          .style('opacity', 1)
          .html(`\n            <div class="tt-title">${d.ticker}</div>\n            <div>${d.fullName}</div>\n            <div class="tt-sector">${d.sector}</div>\n          `);
      })
      .on('mousemove', (event, d) => {
        if (d.isETF) return;
        const [x, y] = d3.pointer(event, bubbleContainer);
        tooltip
          .style('left', `${x}px`)
          .style('top', `${y}px`);
      })
      .on('mouseleave', () => {
        tooltip.style('opacity', 0);
      })
      .on('click', (event, d) => {
        event.stopPropagation();
        setSelected(d.ticker);
      });

    nodes.append('circle')
      .attr('r', (d) => d.radius)
      .attr('fill', (d) => color(d.sector));

    nodes.append('text')
      .text((d) => d.ticker)
      .attr('text-anchor', 'middle')
      .attr('dy', '0.35em')
      .style('font-size', (d) => `${Math.max(10, Math.min(16, d.radius / 2))}px`)
      .style('fill', (d) => textColorFor(color(d.sector)));

    const simulation = d3.forceSimulation(data)
      .force('x', d3.forceX((d) => centers[d.sector].x).strength(0.28))
      .force('y', d3.forceY((d) => centers[d.sector].y).strength(0.28))
      .force('collide', d3.forceCollide((d) => d.radius + 2).iterations(2))
      .force('charge', d3.forceManyBody().strength(-8))
      .force('center', d3.forceCenter(width / 2, height / 2));

    simulation.on('tick', () => {
      nodes.attr('transform', (d) => `translate(${d.x}, ${d.y})`);
    });

    svg.on('click', () => {
      state.selected = null;
      updateSelection();
    });

    state.nodes = nodes;
    state.simulation = simulation;

    buildLegend(sectors, color);
  };

  const handleResize = (data) => {
    if (!state.simulation) return;
    buildChart(data);
    updateSelection();
  };

  const init = () => {
    d3.csv(dataPath, (d) => {
      const marketCapValue = +d.marketCap;
      const isETF = !Number.isFinite(marketCapValue) || marketCapValue <= 0;
      return {
        ticker: d.ticker,
        sector: d.sector,
        fullName: d['full name'],
        marketCapValue,
        isETF,
        displayMarketCap: formatMarketCap(marketCapValue)
      };
    })
      .then((data) => {
        if (!data.length) {
          showWarning('No stock data found.');
          return;
        }
        buildTable(data);
        buildChart(data);
        loadSparklines(data);

        window.addEventListener('resize', () => handleResize(data));
      })
      .catch(() => {
        showWarning('Stock data could not be loaded. If you opened this via file://, try a local server.');
      });
  };

  init();
})();
JS"}

{"cmd":"node - <<'NODE'
const fs = require('fs');
const path = require('path');

const stockCsv = fs.readFileSync('/root/data/stock-descriptions.csv', 'utf8');

function parseCSV(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const next = text[i + 1];
    if (inQuotes) {
      if (char === '"') {
        if (next === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += char;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
      } else if (char === ',') {
        row.push(field);
        field = '';
      } else if (char === '\n') {
        row.push(field);
        rows.push(row);
        row = [];
        field = '';
      } else if (char === '\r') {
        // skip
      } else {
        field += char;
      }
    }
  }
  if (field.length || row.length) {
    row.push(field);
    rows.push(row);
  }
  const headers = rows.shift();
  return rows.map((r) => {
    const obj = {};
    headers.forEach((h, i) => {
      obj[h] = r[i] ?? '';
    });
    return obj;
  });
}

const stockRecords = parseCSV(stockCsv);
const stockData = stockRecords.map((d) => ({
  ticker: d.ticker,
  sector: d.sector,
  fullName: d['full name'],
  marketCap: d.marketCap
}));

const stockDataJs = `window.STOCK_DATA = ${JSON.stringify(stockData)};\n`;
fs.writeFileSync('/root/output/js/stock-data.js', stockDataJs);

const priceDir = '/root/data/indiv-stock';
const files = fs.readdirSync(priceDir).filter((f) => f.endsWith('.csv'));
const priceHistory = {};

function sampleSeries(series, maxPoints) {
  if (series.length <= maxPoints) return series;
  const step = Math.ceil(series.length / maxPoints);
  return series.filter((_, i) => i % step === 0);
}

for (const file of files) {
  const ticker = path.basename(file, '.csv');
  const content = fs.readFileSync(path.join(priceDir, file), 'utf8').trim();
  if (!content) continue;
  const lines = content.split('\n');
  const header = lines.shift().split(',');
  const dateIdx = header.indexOf('Date');
  const closeIdx = header.indexOf('Close');
  const series = [];
  for (const line of lines) {
    if (!line) continue;
    const parts = line.split(',');
    const date = parts[dateIdx];
    const close = parseFloat(parts[closeIdx]);
    if (date && Number.isFinite(close)) {
      series.push([date, close]);
    }
  }
  const sampled = sampleSeries(series, 120);
  priceHistory[ticker] = sampled;
}

const priceHistoryJs = `window.PRICE_HISTORY = ${JSON.stringify(priceHistory)};\n`;
fs.writeFileSync('/root/output/js/price-history.js', priceHistoryJs);

console.log('Wrote stock-data.js and price-history.js');
NODE"}

